package scopedhttp

import (
	_ "embed"
	"testing"
)

// Generated by the app's SingboxConfigBuilder with a documentation-only literal
// SOCKS node and all builder defaults. In particular, defaults enable TFO, add
// tcp_multi_path:false and select a hostname DoH server detouring via select.
//
//go:embed testdata/app-default-socks.json
var appDefaultSOCKS []byte

func TestActualAppDefaultConfigurationIsAccepted(t *testing.T) {
	plan, err := NewPlan(appDefaultSOCKS, []string{"select", "literal-socks"})
	if err != nil {
		t.Fatalf("app default configuration rejected: %v", err)
	}
	if plan.proxy.typ != "socks" || plan.proxy.tag != "literal-socks" || plan.dns.typ != "https" || plan.dns.host != "dns.cloudflare.com" || plan.dns.path != "/dns-query" {
		t.Fatal("app default route/DNS identity changed")
	}
	if _, err := NewPlan(appDefaultSOCKS, []string{"literal-socks"}); err == nil {
		t.Fatal("leaf-only query bypassed the required DNS selector identity")
	}
}
